const QUNUT = [[1,[{"ar":"صَدَقَ اللَّهُ الْعَظِيمُ الَّذِي لَا إِلَٰهَ إِلَّا هُوَ الْمُتَوَحِّدُ بِالْجَلَالِ وَالْكَمَالِ وَالْجَمَالِ تَعَظُّمًا وَتَكَبُّرًا","lat":"Ṣadaqa Allāhu-l-ʿAẓīmu-lladhī lā ilāha illā Huwa-l-Mutawaḥḥidu bi-l-Jalāli wa-l-Kamāli wa-l-Jamāli taʿaẓẓuman wa takabburā","en":"Allah the Almighty has spoken the truth — there is no god but Him, the One alone in Majesty, Perfection and Beauty, in greatness and grandeur.","de":"Allah, der Allmächtige, hat die Wahrheit gesprochen – es gibt keinen Gott außer Ihm, dem Einzigartigen in Erhabenheit, Vollkommenheit und Schönheit, in Größe und Hoheit.","open":false},{"ar":"الْمُتَفَرِّدُ بِتَصْرِيفِ الْأَحْوَالِ عَلَى التَّفْصِيلِ وَالْإِجْمَالِ تَقْدِيرًا وَتَدْبِيرًا","lat":"Al-Mutafarridu bi-taṣrīfi-l-aḥwāli ʿalā-t-tafṣīli wa-l-ijmāli taqdīran wa tadbīrā","en":"The One alone in governing all affairs, in detail and as a whole, by decree and design.","de":"Der Einzige, der alle Angelegenheiten lenkt, im Einzelnen wie im Ganzen, durch Bestimmung und Führung.","open":false},{"ar":"الْمُتَعَالِي بِعَظَمَتِهِ وَمَجْدِهِ الَّذِي أَنْزَلَ الْفُرْقَانَ عَلَى عَبْدِهِ لِيَكُونَ لِلْعَالَمِينَ نَذِيرًا","lat":"Al-Mutaʿālī bi-ʿaẓamatihi wa majdihi-lladhī anzala-l-Furqāna ʿalā ʿabdihi li-yakūna li-l-ʿālamīna nadhīrā","en":"The Most High in His majesty and glory, who sent down the Criterion (the Qurʾān) upon His servant, that he might be a warner to all the worlds.","de":"Der Erhabene in Seiner Macht und Herrlichkeit, der den Furqān (den Qurʾān) auf Seinen Diener herabsandte, damit er den Welten ein Warner sei.","open":false},{"ar":"وَصَدَقَ رَسُولُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَسْلِيمًا كَثِيرًا","lat":"Wa ṣadaqa Rasūluhu ṣallā Allāhu ʿalayhi wa sallama taslīman kathīrā","en":"And His Messenger — may Allah bless him and grant him much peace — spoke the truth.","de":"Und Sein Gesandter – Allahs Segen und reichlich Frieden seien auf ihm – hat die Wahrheit gesagt.","open":false},{"ar":"الَّذِي أَرْسَلَهُ اللَّهُ إِلَى الْإِنْسِ وَالْجِنِّ بَشِيرًا وَنَذِيرًا","lat":"Alladhī arsalahu Allāhu ila-l-insi wa-l-jinni bashīran wa nadhīrā","en":"Whom Allah sent to mankind and jinn as a bringer of good news and a warner.","de":"Den Allah zu Menschen und Dschinn als Verkünder froher Botschaft und als Warner sandte.","open":false},{"ar":"وَدَاعِيًا إِلَى اللَّهِ بِإِذْنِهِ وَسِرَاجًا مُنِيرًا","lat":"Wa dāʿiyan ila Allāhi bi-idhnihi wa sirājan munīrā","en":"And a caller to Allah by His permission, and a light-giving lamp.","de":"Und ein Rufer zu Allah mit Seiner Erlaubnis und eine leuchtende Lampe.","open":false},{"ar":"صَدَقَ اللَّهُ الْحَقُّ الْعَظِيمُ الَّذِي نَزَّلَ الْقُرْآنَ الْكَرِيمَ فِي شَهْرِ رَمَضَانَ هُدًى وَتَذْكِيرًا","lat":"Ṣadaqa Allāhu-l-Ḥaqqu-l-ʿAẓīmu-lladhī nazzala-l-Qurʾāna-l-Karīma fī shahri Ramaḍāna hudan wa tadhkīrā","en":"Allah, the True, the Almighty, has spoken the truth — He who sent down the Noble Qurʾān in the month of Ramaḍān as guidance and reminder.","de":"Allah, der Wahre, der Allmächtige, hat die Wahrheit gesprochen – Er, der den Edlen Qurʾān im Monat Ramaḍān als Rechtleitung und Ermahnung herabsandte.","open":false},{"ar":"صَدَقَ اللَّهُ الْحَقُّ الْعَظِيمُ الَّذِي سَنَّ الدِّينَ وَشَرَعَ","lat":"Ṣadaqa Allāhu-l-Ḥaqqu-l-ʿAẓīmu-lladhī sanna-d-dīna wa sharaʿ","en":"Allah, the True, the Almighty, has spoken the truth — He who established the religion and laid down its law.","de":"Allah, der Wahre, der Allmächtige, hat die Wahrheit gesprochen – Er, der die Religion eingesetzt und ihr Gesetz festgelegt hat.","open":false},{"ar":"وَأَنَارَ النُّورَ وَشَاءَ مَا شَاءَ","lat":"Wa anāra-n-nūra wa shāʾa mā shāʾ","en":"And lit up the light, and willed whatever He willed.","de":"Und das Licht erleuchtete und wollte, was Er wollte.","open":false},{"ar":"وَلَا إِلَٰهَ إِلَّا هُوَ جَعَلَ السَّمَاءَ سَقْفًا بِدُونِ عَمَدٍ رَفَعَهَا","lat":"Wa lā ilāha illā Huwa jaʿala-s-samāʾa saqfan bidūni ʿamadin rafaʿahā","en":"And there is no god but Him, who made the sky a roof, raised without pillars.","de":"Und es gibt keinen Gott außer Ihm, der den Himmel zu einem Dach machte, ohne Stützen erhoben.","open":false},{"ar":"وَالْأَرْضَ بِسَاطًا فَرَشَهَا","lat":"Wa-l-arḍa bisāṭan farashahā","en":"And the earth a carpet, spread out.","de":"Und die Erde als Teppich ausgebreitet.","open":false}]],[2,[{"ar":"صَدَقَ اللَّهُ الْعَظِيمُ الَّذِي دَبَّرَ الدُّهُورَ وَقَدَّرَ الْمَقْدُورَ وَصَرَّفَ الْأُمُورَ","lat":"Ṣadaqa Allāhu-l-ʿAẓīmu-lladhī dabbara-d-duhūra wa qaddara-l-maqdūra wa ṣarrafa-l-umūr","en":"Allah the Almighty has spoken the truth — He who ordered the ages, decreed what is decreed, and directed all affairs.","de":"Allah, der Allmächtige, hat die Wahrheit gesprochen – Er, der die Zeitalter ordnete, das Bestimmte festlegte und alle Angelegenheiten lenkte.","open":false},{"ar":"وَعَلِمَ وَسَاوِسَ الصُّدُورِ","lat":"Wa ʿalima wasāwisa-ṣ-ṣudūr","en":"And knew the whispers of hearts.","de":"Und kannte die Einflüsterungen der Herzen.","open":false},{"ar":"وَأَنْزَلَ الْقُرْآنَ هُدًى وَنُورًا","lat":"Wa anzala-l-Qurʾāna hudan wa nūrā","en":"And sent down the Qurʾān as guidance and light.","de":"Und sandte den Qurʾān als Rechtleitung und Licht herab.","open":false},{"ar":"صَدَقَ اللَّهُ الْعَظِيمُ الَّذِي أَظْفَرَ مَنِ اتَّقَى","lat":"Ṣadaqa Allāhu-l-ʿAẓīmu-lladhī aẓfara mani-ttaqā","en":"Allah the Almighty has spoken the truth — He who grants victory to whoever is mindful of Him.","de":"Allah, der Allmächtige, hat die Wahrheit gesprochen – Er, der dem zum Sieg verhilft, der Ihn fürchtet.","open":false},{"ar":"وَعَلَى مَنِ امْتُحِنَ","lat":"Wa ʿalā mani-mtuḥina","en":"And upon whoever is tested.","de":"Und dem, der geprüft wird.","open":false},{"ar":"وَذَلَّ كُلُّ شَيْءٍ لِعَظَمَتِهِ وَخَضَعَ","lat":"Wa dhalla kullu shayʾin li-ʿaẓamatihi wa khaḍaʿ","en":"And everything is humbled before His greatness and has submitted.","de":"Und alles beugt sich vor Seiner Größe und unterwirft sich.","open":false},{"ar":"صَدَقَ اللَّهُ الْحَقُّ التَّوَّابُ الْغَفُورُ الْوَهَّابُ","lat":"Ṣadaqa Allāhu-l-Ḥaqqu-t-Tawwābu-l-Ghafūru-l-Wahhāb","en":"Allah, the True, has spoken the truth — the Ever-Relenting, the All-Forgiving, the Giver of all.","de":"Allah, der Wahre, hat die Wahrheit gesprochen – der Vielvergebende, der Allverzeihende, der Freigebige.","open":false},{"ar":"الَّذِي خَضَعَتْ لِعَظَمَتِهِ الرِّقَابُ","lat":"Alladhī khaḍaʿat li-ʿaẓamatihi-r-riqāb","en":"Before whose greatness every neck bows.","de":"Vor dessen Größe sich jeder Nacken beugt.","open":false},{"ar":"وَلَا نُطِيقُ شِدَّةَ سُلْطَانِهِ","lat":"Wa lā nuṭīqu shiddata sulṭānih","en":"And we cannot withstand the intensity of His power.","de":"Und wir können die Macht Seiner Herrschaft nicht ertragen.","open":false},{"ar":"يُسَبِّحُ بِحَمْدِهِ الرَّعْدُ وَالسَّحَابُ","lat":"Yusabbiḥu bi-ḥamdihi-r-raʿdu wa-s-saḥāb","en":"The thunder and the clouds glorify Him with praise.","de":"Der Donner und die Wolken preisen Ihn mit Lobpreis.","open":false},{"ar":"رَبُّ الْأَرْبَابِ وَمُنَزِّلُ الْكِتَابِ","lat":"Rabbu-l-arbābi wa munazzilu-l-kitāb","en":"Lord of lords, and Revealer of the Book.","de":"Herr der Herren und Herabsender des Buches.","open":false},{"ar":"وَهَازِمُ الْأَحْزَابِ","lat":"Wa hāzimu-l-aḥzāb","en":"And the Defeater of the confederates.","de":"Und der Besieger der Verbündeten.","open":false},{"ar":"وَمُسَبِّبُ الْأَسْبَابِ","lat":"Wa musabbibu-l-asbāb","en":"And the Causer of all causes.","de":"Und der Urheber aller Ursachen.","open":false},{"ar":"لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْنَا وَإِلَيْهِ الْمَآبُ","lat":"Lā ilāha illā Huwa ʿalayhi tawakkalnā wa ilayhi-l-maʾāb","en":"There is no god but Him; upon Him we rely, and to Him is the return.","de":"Es gibt keinen Gott außer Ihm; auf Ihn vertrauen wir, und zu Ihm ist die Rückkehr.","open":false},{"ar":"صَدَقَ اللَّهُ الْحَقُّ الْوَاحِدُ الْقَهَّارُ الْعَظِيمُ","lat":"Ṣadaqa Allāhu-l-Ḥaqqu-l-Wāḥidu-l-Qahhāru-l-ʿAẓīm","en":"Allah, the True, has spoken the truth — the One, the All-Compelling, the Almighty.","de":"Allah, der Wahre, hat die Wahrheit gesprochen – der Eine, der Allbezwingende, der Allmächtige.","open":false},{"ar":"ذُو الْجَلَالِ وَالْإِكْرَامِ وَالْعَظَمَةِ وَالْإِنْعَامِ","lat":"Dhu-l-Jalāli wa-l-Ikrāmi wa-l-ʿAẓamati wa-l-Inʿām","en":"Possessor of Majesty, Honor, Greatness and Bounty.","de":"Besitzer von Erhabenheit, Großzügigkeit, Größe und Wohltat.","open":false}]],[3,[{"ar":"الْكَرِيمُ الَّذِي مَنَّ بِنَفْعِهِ عَلَى مَنْ شَاءَ مِنْ عِبَادِهِ","lat":"Al-Karīmu-lladhī manna bi-nafʿihi ʿalā man shāʾa min ʿibādih","en":"The Generous, who bestows His benefit upon whomever He wills of His servants.","de":"Der Großzügige, der Seinen Nutzen gewährt, wem Er will von Seinen Dienern.","open":false},{"ar":"الْقَيُّومُ الَّذِي لَا يَنْفَعُ وَلَا يَضُرُّ إِلَّا هُوَ","lat":"Al-Qayyūmu-lladhī lā yanfaʿu wa lā yaḍurru illā Huwa","en":"The Self-Sustaining, from whom alone benefit or harm comes.","de":"Der Beständige, von dem allein Nutzen oder Schaden kommt.","open":false},{"ar":"إِلَٰهَنَا","lat":"Ilāhanā","en":"Our God,","de":"Unser Gott,","open":false},{"ar":"تَفَضَّلْتَ فَعَمَّتْ أَفْضَالُكَ","lat":"Tafaḍḍalta fa ʿammat afḍāluk","en":"You have been gracious, so Your favors have encompassed all.","de":"Du warst gnädig, sodass Deine Gaben alles umfassten.","open":false},{"ar":"إِلَٰهَنَا","lat":"Ilāhanā","en":"Our God,","de":"Unser Gott,","open":false},{"ar":"غَفَرْتَ فَتَكَامَلَ إِحْسَانُكَ","lat":"Ghafarta fa takāmala iḥsānuk","en":"You have forgiven, so Your kindness became complete.","de":"Du hast vergeben, sodass Deine Güte vollkommen wurde.","open":false},{"ar":"جَلَّ جَلَالُكَ","lat":"Jalla Jalāluk","en":"Majestic is Your majesty.","de":"Erhaben ist Deine Erhabenheit.","open":false},{"ar":"تَعَالَيْتَ فِي دُنُوِّكَ","lat":"Taʿālayta fī dunuwwik","en":"You are exalted even while being near.","de":"Du bist erhaben, selbst in Deiner Nähe.","open":false},{"ar":"وَتَقَرَّبْتَ فِي عُلُوِّكَ","lat":"Wa taqarrabta fī ʿuluwwik","en":"And You draw near while being above all.","de":"Und Du näherst Dich in Deiner Erhabenheit.","open":false},{"ar":"أَنْتَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ","lat":"Anta-l-Awwalu wa-l-Ākhiru wa-ẓ-Ẓāhiru wa-l-Bāṭin","en":"You are the First and the Last, the Manifest and the Hidden.","de":"Du bist der Erste und der Letzte, der Offenbare und der Verborgene.","open":false},{"ar":"أَنْتَ الْوَاحِدُ الْأَحَدُ الْفَرْدُ الصَّمَدُ","lat":"Anta-l-Wāḥidu-l-Aḥadu-l-Fardu-ṣ-Ṣamad","en":"You are the One, the Unique, the Single, the Eternal Refuge.","de":"Du bist der Eine, der Einzige, der Alleinstehende, der ewig Erbetene.","open":false},{"ar":"لَكَ خَضَعَ مَنْ سَجَدَ وَذَلَّ مَنْ وَجَدَ","lat":"Laka khaḍaʿa man sajada wa dhalla man wajad","en":"To You bows whoever prostrates, and submits whoever finds You.","de":"Vor Dir beugt sich, wer niederfällt, und unterwirft sich, wer Dich findet.","open":false},{"ar":"إِلَٰهَنَا كَيْفَ يُنَادِيكَ فِي الصَّلَوَاتِ مَنْ يَعْصِيكَ فِي الْخَلَوَاتِ لَوْلَا حِلْمُكَ","lat":"Ilāhanā kayfa yunādīka fi-ṣ-ṣalawāti man yaʿṣīka fi-l-khalawāti lawlā ḥilmuk","en":"Our God, how could one who disobeys You in private call upon You in prayer, were it not for Your forbearance?","de":"Unser Gott, wie könnte Dich jemand im Gebet anrufen, der Dir im Verborgenen ungehorsam ist, wäre nicht Deine Nachsicht?","open":false},{"ar":"وَكَيْفَ يَدْعُوكَ لِلْحَاجَاتِ مَنْ يَنْسَاكَ عِنْدَ الشَّهَوَاتِ لَوْلَا فَضْلُكَ","lat":"Wa kayfa yadʿūka li-l-ḥājāti man yansāka ʿinda-sh-shahawāti lawlā faḍluk","en":"And how could one who forgets You amid desires call upon You in need, were it not for Your grace?","de":"Und wie könnte Dich jemand in Nöten anrufen, der Dich bei Begierden vergisst, wäre nicht Deine Gnade?","open":false},{"ar":"إِلَٰهَنَا","lat":"Ilāhanā","en":"Our God,","de":"Unser Gott,","open":false},{"ar":"مَنْ إِلَيْهِ نَقْصِدُ وَأَنْتَ وَحْدَكَ الْمَقْصُودُ","lat":"Man ilayhi naqṣidu wa anta waḥdaka-l-maqṣūd","en":"To whom do we turn, when You alone are the goal?","de":"Zu wem sollten wir uns wenden, wenn Du allein das Ziel bist?","open":false}]],[4,[{"ar":"وَإِلَى مَنْ نَتَوَجَّهُ وَأَنْتَ وَحْدَكَ الْمَوْجُودُ","lat":"Wa ilā man natawajjahu wa anta waḥdaka-l-mawjūd","en":"And to whom do we direct ourselves, when You alone truly exist?","de":"Und an wen sollten wir uns wenden, wenn Du allein der wahrhaft Seiende bist?","open":false},{"ar":"وَمَنْ ذَا الَّذِي يُعْطِي وَأَنْتَ صَاحِبُ الْجُودِ","lat":"Wa man dha-lladhī yuʿṭī wa anta ṣāḥibu-l-jūd","en":"And who is it that gives, when You are the Possessor of generosity?","de":"Und wer ist es, der gibt, wenn Du der Herr der Großzügigkeit bist?","open":false},{"ar":"وَمَنْ ذَا الَّذِي نَسْأَلُ وَأَنْتَ رَبُّ الْمَعْدُودِ","lat":"Wa man dha-lladhī nasʾalu wa anta Rabbu-l-maʿdūd","en":"And who is it that we ask, when You are the Lord of all that is counted?","de":"Und wen sollten wir bitten, wenn Du der Herr alles Gezählten bist?","open":false},{"ar":"اللَّهُمَّ يَا قَاضِيَ حَاجَتِنَا بِجَمِيعِنَا مُتَوَسِّلِينَ","lat":"Allāhumma yā Qāḍiya ḥājatinā bi-jamīʿinā mutawassilīn","en":"O Allah, Fulfiller of our need, all of us pleading before You.","de":"O Allah, Erfüller unserer Bitte, wir alle flehen zu Dir.","open":true},{"ar":"وَبِكَ الْعِزُّ لَا بِغَيْرِكَ","lat":"Wa bika-l-ʿizzu lā bi-ghayrik","en":"With You is might, not with other than You.","de":"Bei Dir ist Macht, nicht bei einem anderen.","open":false},{"ar":"وَإِلَى بَابِكَ سَائِلِينَ","lat":"Wa ilā bābika sāʾilīn","en":"And at Your door we are asking.","de":"Und an Deiner Tür bitten wir.","open":false},{"ar":"فَلَا تَرُدَّنَا خَائِبِينَ","lat":"Fa lā taruddanā khāʾibīn","en":"So do not turn us away disappointed.","de":"So weise uns nicht enttäuscht zurück.","open":false},{"ar":"وَاغْفِرْ لَنَا ذُنُوبَنَا أَجْمَعِينَ","lat":"Wa-ghfir lanā dhunūbanā ajmaʿīn","en":"And forgive us all our sins.","de":"Und vergib uns all unsere Sünden.","open":false},{"ar":"وَاقْبَلْ دُعَاءَنَا وَاجْعَلْ سَعْيَنَا مَشْكُورًا","lat":"Wa-qbal duʿāʾanā wa-jʿal saʿyanā mashkūrā","en":"And accept our supplication, and make our effort appreciated.","de":"Und nimm unser Bittgebet an, und mache unsere Mühe anerkannt.","open":false},{"ar":"وَعَمَلَنَا مَشْكُورًا","lat":"Wa ʿamalanā mashkūrā","en":"And our deeds appreciated.","de":"Und unsere Taten anerkannt.","open":false},{"ar":"وَأَعْتِقْ رِقَابَنَا وَوَالِدَيْنَا وَالْمُسْلِمِينَ أَجْمَعِينَ مِنَ النَّارِ","lat":"Wa aʿtiq riqābanā wa wālidaynā wa-l-Muslimīna ajmaʿīna mina-n-nār","en":"And free our necks, our parents, and all the Muslims from the Fire.","de":"Und befreie uns, unsere Eltern und alle Muslime vom Feuer.","open":false},{"ar":"اللَّهُمَّ اجْعَلِ الْمَوْتَ خَيْرَ غَائِبٍ نَنْتَظِرُهُ","lat":"Allāhumma-jʿali-l-mawta khayra ghāʾibin nantaẓiruh","en":"O Allah, make death the best of absent things that we await.","de":"O Allah, mache den Tod zum besten der verborgenen Dinge, die wir erwarten.","open":true},{"ar":"وَالْقَبْرُ خَيْرُ بَيْتٍ نُعَمِّرُهُ","lat":"Wa-l-qabru khayru baytin nuʿammiruh","en":"And the grave the best house we build up.","de":"Und das Grab das beste Haus, das wir erbauen.","open":false},{"ar":"وَاجْعَلْ مَا بَعْدَهُ خَيْرًا لَنَا مِنْهُ","lat":"Wa-jʿal mā baʿdahu khayran lanā minhu","en":"And make what comes after it better for us than it.","de":"Und mache das, was danach kommt, besser für uns als es selbst.","open":false},{"ar":"بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ","lat":"Bi-raḥmatika yā Arḥama-r-Rāḥimīn","en":"By Your mercy, O Most Merciful of the merciful.","de":"Durch Deine Barmherzigkeit, o Barmherzigster der Barmherzigen.","open":false},{"ar":"اللَّهُمَّ أَنْزِلْ عَلَيْنَا فِي قُبُورِنَا النُّورَ","lat":"Allāhumma anzil ʿalaynā fī qubūrinā-n-nūr","en":"O Allah, send down light upon us in our graves.","de":"O Allah, sende uns Licht in unseren Gräbern herab.","open":true}]],[5,[{"ar":"وَالْفَرْحَةَ وَالسُّرُورَ","lat":"Wa-l-farḥata wa-s-surūr","en":"And joy and happiness.","de":"Und Freude und Glückseligkeit.","open":false},{"ar":"وَأَجْزِنَا بِالْإِحْسَانِ إِحْسَانًا","lat":"Wa ajzinā bi-l-iḥsāni iḥsānā","en":"And reward us for good with good.","de":"Und belohne uns für Gutes mit Gutem.","open":false},{"ar":"وَبِالسَّيِّئَاتِ غُفْرَانًا","lat":"Wa bi-s-sayyiʾāti ghufrānā","en":"And for bad deeds with forgiveness.","de":"Und für Schlechtes mit Vergebung.","open":false},{"ar":"اللَّهُمَّ اجْعَلْنَا بِهَٰذَا الْقُرْآنِ مُصَدِّقِينَ","lat":"Allāhumma-jʿalnā bi-hādhā-l-Qurʾāni muṣaddiqīn","en":"O Allah, make us believers in this Qurʾān.","de":"O Allah, mache uns zu Gläubigen an diesen Qurʾān.","open":true},{"ar":"وَفِيمَا عِنْدَكَ إِلَٰهَنَا رَاغِبِينَ","lat":"Wa fīmā ʿindaka ilāhanā rāghibīn","en":"And desirous, our God, of what is with You.","de":"Und begierig, unser Gott, nach dem, was bei Dir ist.","open":false},{"ar":"وَلِرَحْمَتِكَ يَا مَوْلَانَا طَالِبِينَ","lat":"Wa li-raḥmatika yā Mawlānā ṭālibīn","en":"And seekers of Your mercy, O our Master.","de":"Und Suchende nach Deiner Barmherzigkeit, o unser Herr.","open":false},{"ar":"وَعَنِ السَّيِّئَاتِ عَازِفِينَ","lat":"Wa ʿani-s-sayyiʾāti ʿāzifīn","en":"And turning away from bad deeds.","de":"Und uns von schlechten Taten abwendend.","open":false},{"ar":"وَعَنِ الْمُحَرَّمَاتِ بَعِيدِينَ","lat":"Wa ʿani-l-muḥarramāti baʿīdīn","en":"And far from what is forbidden.","de":"Und fern von dem Verbotenen.","open":false},{"ar":"وَمِنْ عِقَابِكَ خَائِفِينَ","lat":"Wa min ʿiqābika khāʾifīn","en":"And fearful of Your punishment.","de":"Und furchtsam vor Deiner Strafe.","open":false},{"ar":"وَاحْشُرْنَا مَعَ النَّبِيِّينَ وَالصِّدِّيقِينَ","lat":"Wa-ḥshurnā maʿa-n-nabiyyīna wa-ṣ-ṣiddīqīn","en":"And gather us with the prophets and the truthful.","de":"Und versammle uns mit den Propheten und den Wahrhaftigen.","open":false},{"ar":"وَالشُّهَدَاءِ وَالْأَبْرَارِ وَالصَّالِحِينَ","lat":"Wa-sh-shuhadāʾi wa-l-abrāri wa-ṣ-ṣāliḥīn","en":"And the martyrs, the righteous and the good.","de":"Und den Märtyrern, den Rechtschaffenen und den Guten.","open":false},{"ar":"وَلَا تَجْعَلْنَا يَا مَوْلَانَا مِمَّنِ اسْتَهْوَتْهُمُ الشَّيَاطِينُ","lat":"Wa lā tajʿalnā yā Mawlānā mimmani-stahwat-humu-sh-shayāṭīn","en":"And do not make us, O our Master, among those whom the devils have led astray.","de":"Und mache uns nicht, o unser Herr, zu denen, die die Teufel verführt haben.","open":false},{"ar":"وَشَغَلَتْهُمُ الدُّنْيَا عَنِ الدِّينِ","lat":"Wa shaghalat-humu-d-dunyā ʿani-d-dīn","en":"And whom the world distracted from religion.","de":"Und die die Welt von der Religion abgelenkt hat.","open":false},{"ar":"وَأَصْبَحُوا مِنَ النَّادِمِينَ","lat":"Wa aṣbaḥū mina-n-nādimīn","en":"And who became among the regretful.","de":"Und die zu den Reumütigen wurden.","open":false},{"ar":"وَفِي الْآخِرَةِ مِنَ الْخَاسِرِينَ","lat":"Wa fi-l-ākhirati mina-l-khāsirīn","en":"And in the Hereafter among the losers.","de":"Und im Jenseits zu den Verlierern.","open":false},{"ar":"اللَّهُمَّ إِنَّا عَبِيدُكَ بَنُو عَبِيدِكَ بَنُو إِمَائِكَ","lat":"Allāhumma innā ʿabīduka banū ʿabīdika banū imāʾik","en":"O Allah, we are Your servants, children of Your servants, children of Your maidservants.","de":"O Allah, wir sind Deine Diener, Söhne Deiner Diener, Söhne Deiner Dienerinnen.","open":true},{"ar":"نَوَاصِينَا بِيَدِكَ","lat":"Nawāṣīnā bi-yadik","en":"Our forelocks are in Your hand.","de":"Unsere Stirnlocken sind in Deiner Hand.","open":false}]],[6,[{"ar":"مَاضٍ فِينَا حُكْمُكَ","lat":"Māḍin fīnā ḥukmuk","en":"Your judgment over us is in effect.","de":"Dein Urteil über uns ist bindend.","open":false},{"ar":"عَدْلٌ فِينَا قَضَاؤُكَ","lat":"ʿAdlun fīnā qaḍāʾuk","en":"Your decree over us is just.","de":"Dein Ratschluss über uns ist gerecht.","open":false},{"ar":"نَسْأَلُكَ اللَّهُمَّ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ","lat":"Nasʾaluka Allāhumma bi-kulli ismin huwa laka sammayta bihi nafsak","en":"We ask You, O Allah, by every name that is Yours, by which You have named Yourself,","de":"Wir bitten Dich, o Allah, bei jedem Namen, der Dein ist, mit dem Du Dich selbst benannt hast,","open":false},{"ar":"أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ","lat":"Aw anzaltahu fī kitābik","en":"or revealed in Your Book,","de":"oder den Du in Deinem Buch herabgesandt hast,","open":false},{"ar":"أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ","lat":"Aw ʿallamtahu aḥadan min khalqik","en":"or taught to anyone of Your creation,","de":"oder den Du einem Deiner Geschöpfe gelehrt hast,","open":false},{"ar":"أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ","lat":"Awi-staʾtharta bihi fī ʿilmi-l-ghaybi ʿindak","en":"or kept to Yourself in the knowledge of the unseen with You:","de":"oder den Du für Dich behalten hast im Wissen des Verborgenen bei Dir:","open":false},{"ar":"أَنْ تَجْعَلَ الْقُرْآنَ الْعَظِيمَ رَبِيعَ قُلُوبِنَا","lat":"An tajʿala-l-Qurʾāna-l-ʿaẓīma rabīʿa qulūbinā","en":"that You make the Great Qurʾān the spring of our hearts,","de":"dass Du den Großen Qurʾān zum Frühling unserer Herzen machst,","open":false},{"ar":"وَنُورَ صُدُورِنَا","lat":"Wa nūra ṣudūrinā","en":"and the light of our chests,","de":"und zum Licht unserer Brust,","open":false},{"ar":"وَجِلَاءَ أَحْزَانِنَا","lat":"Wa jilāʾa aḥzāninā","en":"and the removal of our sorrows,","de":"und zur Vertreibung unserer Trauer,","open":false},{"ar":"وَذَهَابَ هُمُومِنَا","lat":"Wa dhahāba humūminā","en":"and the departure of our anxieties,","de":"und zum Verschwinden unserer Sorgen,","open":false},{"ar":"وَغُمُومِنَا","lat":"Wa ghumūminā","en":"and our distress,","de":"und unseres Kummers,","open":false},{"ar":"وَسُقْنَا إِلَى جَنَّاتِكَ جَنَّاتِ النَّعِيمِ","lat":"Wa suqnā ilā jannātika jannāti-n-naʿīm","en":"and drive us to Your gardens, the gardens of bliss.","de":"und treibe uns zu Deinen Gärten, den Gärten der Wonne.","open":false},{"ar":"اللَّهُمَّ اجْعَلِ الْقُرْآنَ لِقُلُوبِنَا ضِيَاءً","lat":"Allāhumma-jʿali-l-Qurʾāna li-qulūbinā ḍiyāʾā","en":"O Allah, make the Qurʾān a light for our hearts,","de":"O Allah, mache den Qurʾān zu einem Licht für unsere Herzen,","open":true},{"ar":"وَلِأَحْزَانِنَا جِلَاءً","lat":"Wa li-aḥzāninā jilāʾā","en":"and a remover of our sorrows,","de":"und zur Vertreibung unserer Trauer,","open":false},{"ar":"وَلِذُنُوبِنَا مُمَحِّصًا","lat":"Wa li-dhunūbinā mumaḥḥiṣā","en":"and a purifier of our sins,","de":"und zur Läuterung unserer Sünden,","open":false},{"ar":"وَعَنِ النَّارِ لَنَا مُخَلِّصًا","lat":"Wa ʿani-n-nāri lanā mukhalliṣā","en":"and a deliverer for us from the Fire,","de":"und zur Rettung vor dem Feuer,","open":false},{"ar":"وَفِي الْقَبْرِ لَنَا مُؤْنِسًا","lat":"Wa fi-l-qabri lanā muʾnisā","en":"and a companion for us in the grave.","de":"und zum Begleiter für uns im Grab.","open":false}]],[7,[{"ar":"وَعَلَى الصِّرَاطِ مُرْشِدًا","lat":"Wa ʿala-ṣ-ṣirāṭi murshidā","en":"and a guide upon the Path,","de":"und zum Führer auf dem Weg,","open":false},{"ar":"وَإِلَى الْجَنَّةِ دَلِيلًا","lat":"Wa ila-l-jannati dalīlā","en":"and a guide to Paradise.","de":"und zum Wegweiser ins Paradies.","open":false},{"ar":"اللَّهُمَّ اجْعَلْنَا مِنْ أَهْلِ الْقُرْآنِ","lat":"Allāhumma-jʿalnā min ahli-l-Qurʾān","en":"O Allah, make us among the people of the Qurʾān,","de":"O Allah, mache uns zu den Leuten des Qurʾān,","open":true},{"ar":"الَّذِينَ هُمْ أَهْلُكَ وَخَاصَّتُكَ يَا رَبَّ الْعَالَمِينَ","lat":"Alladhīna hum ahluka wa khāṣṣatuka yā Rabba-l-ʿĀlamīn","en":"who are Your people and Your chosen ones, O Lord of the worlds:","de":"die Dein Volk und Deine Auserwählten sind, o Herr der Welten:","open":true},{"ar":"وَاجْعَلْنَا مِمَّنْ يُحِلُّ حَلَالَهُ","lat":"Wa-jʿalnā mimman yuḥillu ḥalālah","en":"and make us among those who deem lawful what it makes lawful,","de":"und mache uns zu denen, die erlauben, was er erlaubt,","open":false},{"ar":"وَيُحَرِّمُ حَرَامَهُ","lat":"Wa yuḥarrimu ḥarāmah","en":"and forbid what it forbids,","de":"und verbieten, was er verbietet,","open":false},{"ar":"وَيَعْمَلُ بِمُحْكَمِهِ","lat":"Wa yaʿmalu bi-muḥkamih","en":"and act upon its clear verses,","de":"und nach seinen eindeutigen Versen handeln,","open":false},{"ar":"وَيُؤْمِنُ بِمُتَشَابِهِهِ","lat":"Wa yuʾminu bi-mutashābihih","en":"and believe in its ambiguous verses,","de":"und an seine mehrdeutigen Verse glauben,","open":false},{"ar":"وَيَتْلُوهُ حَقَّ تِلَاوَتِهِ","lat":"Wa yatlūhu ḥaqqa tilāwatih","en":"and recite it as it should truly be recited,","de":"und ihn rezitieren, wie es ihm gebührt,","open":false},{"ar":"عَلَى الْوَجْهِ الَّذِي يُرْضِيكَ عَنَّا","lat":"ʿAla-l-wajhi-lladhī yurḍīka ʿannā","en":"in the manner that pleases You with us.","de":"auf die Weise, die Dich mit uns zufrieden stellt.","open":false},{"ar":"وَاجْعَلْهُ اللَّهُمَّ شَاهِدًا لَنَا يَوْمَ قُدُومِنَا إِلَيْكَ","lat":"Wa-jʿalhu Allāhumma shāhidan lanā yawma qudūminā ilayk","en":"And make it, O Allah, a witness for us on the day we come to You,","de":"Und mache ihn, o Allah, zu einem Zeugen für uns am Tag unserer Ankunft bei Dir,","open":false},{"ar":"حُجَّةً لَنَا يَوْمَ وُقُوفِنَا بَيْنَ يَدَيْكَ","lat":"Ḥujjatan lanā yawma wuqūfinā bayna yadayk","en":"an argument for us on the day we stand before You,","de":"ein Beweis für uns am Tag unseres Stehens vor Dir,","open":false},{"ar":"يَا أَرْحَمَ الرَّاحِمِينَ","lat":"Yā Arḥama-r-Rāḥimīn","en":"O Most Merciful of the merciful.","de":"O Barmherzigster der Barmherzigen.","open":false},{"ar":"اللَّهُمَّ اغْفِرْ لِجَمِيعِ مَوْتَى الْمُسْلِمِينَ","lat":"Allāhumma-ghfir li-jamīʿi mawtā-l-Muslimīn","en":"O Allah, forgive all the deceased of the Muslims,","de":"O Allah, vergib allen verstorbenen Muslimen,","open":true},{"ar":"الَّذِينَ شَهِدُوا لَكَ بِالْوَحْدَانِيَّةِ","lat":"Alladhīna shahidū laka bi-l-waḥdāniyyah","en":"who testified to Your oneness","de":"die Dir die Einzigkeit bezeugt haben","open":false},{"ar":"وَلِنَبِيِّكَ بِالرِّسَالَةِ","lat":"Wa li-nabiyyika bi-r-risālah","en":"and to Your Prophet's message,","de":"und Deinem Propheten die Botschaft,","open":false},{"ar":"وَمَاتُوا عَلَى ذَٰلِكَ","lat":"Wa mātū ʿalā dhālik","en":"and died upon that.","de":"und darauf gestorben sind.","open":false}]],[8,[{"ar":"اللَّهُمَّ اغْفِرْ لَهُمْ وَارْحَمْهُمْ","lat":"Allāhumma-ghfir lahum wa-rḥamhum","en":"O Allah, forgive them and have mercy on them,","de":"O Allah, vergib ihnen und erbarme Dich ihrer,","open":true},{"ar":"وَعَافِهِمْ وَاعْفُ عَنْهُمْ","lat":"Wa ʿāfihim wa-ʿfu ʿanhum","en":"and grant them well-being and pardon them,","de":"und gewähre ihnen Wohlergehen und verzeihe ihnen,","open":false},{"ar":"وَوَسِّعْ مُدْخَلَهُمْ","lat":"Wa wassiʿ mudkhalahum","en":"and widen their entry,","de":"und erweitere ihren Eingang,","open":false},{"ar":"وَأَكْرِمْ نُزُلَهُمْ","lat":"Wa akrim nuzulahum","en":"and honor their lodging,","de":"und ehre ihre Herberge,","open":false},{"ar":"وَاغْسِلْهُمْ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ","lat":"Wa-ghsilhum bi-l-māʾi wa-th-thalji wa-l-barad","en":"and wash them with water, snow and hail,","de":"und wasche sie mit Wasser, Schnee und Hagel,","open":false},{"ar":"وَنَقِّهِمْ مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ","lat":"Wa naqqihim mina-dh-dhunūbi wa-l-khaṭāyā kamā yunaqqa-th-thawbu-l-abyaḍu mina-d-danas","en":"and cleanse them of sins and faults as a white garment is cleansed of filth.","de":"und reinige sie von Sünden und Fehlern, wie das weiße Gewand vom Schmutz gereinigt wird.","open":false},{"ar":"اللَّهُمَّ أَنْقِذْهُمْ جَمِيعًا مِنْ ضِيقِ اللُّحُودِ وَمَرَارَةِ الدُّودِ","lat":"Allāhumma anqidhhum jamīʿan min ḍīqi-l-luḥūdi wa marārati-d-dūd","en":"O Allah, save them all from the narrowness of the graves and the bitterness of worms,","de":"O Allah, errette sie alle von der Enge der Gräber und der Bitterkeit der Würmer,","open":true},{"ar":"إِلَى جَنَّاتِ الْخُلُودِ","lat":"Ilā jannāti-l-khulūd","en":"to the gardens of eternity,","de":"zu den Gärten der Ewigkeit,","open":false},{"ar":"فِي سِدْرٍ مَخْضُودٍ","lat":"Fī sidrin makhḍūd","en":"amid thornless lote-trees,","de":"inmitten dornenloser Lotosbäume,","open":false},{"ar":"وَطَلْحٍ مَنْضُودٍ","lat":"Wa ṭalḥin manḍūd","en":"and clustered banana-trees,","de":"und dicht geschichteten Bananenstauden,","open":false},{"ar":"وَظِلٍّ مَمْدُودٍ","lat":"Wa ẓillin mamdūd","en":"and extended shade.","de":"und ausgedehntem Schatten.","open":false},{"ar":"اللَّهُمَّ اجْعَلْهُمْ فِي بُطُونِ الْأَرْضِ مُطْمَئِنِّينَ","lat":"Allāhumma-jʿalhum fī buṭūni-l-arḍi muṭmaʾinnīn","en":"O Allah, make them tranquil in the belly of the earth,","de":"O Allah, mache sie ruhig im Inneren der Erde,","open":true},{"ar":"وَعِنْدَ السُّؤَالِ ثَابِتِينَ","lat":"Wa ʿinda-s-suʾāli thābitīn","en":"and firm when questioned,","de":"und standhaft bei der Befragung,","open":false},{"ar":"وَبِالْحَقِّ نَاطِقِينَ","lat":"Wa bi-l-ḥaqqi nāṭiqīn","en":"and speaking the truth,","de":"und die Wahrheit sprechend,","open":false},{"ar":"وَعَلَى الصِّرَاطِ مُهْتَدِينَ","lat":"Wa ʿala-ṣ-ṣirāṭi muhtadīn","en":"and rightly guided on the Path,","de":"und rechtgeleitet auf dem Weg,","open":false},{"ar":"وَفِي جَنَّاتِ الْفِرْدَوْسِ سَاكِنِينَ","lat":"Wa fī jannāti-l-firdawsi sākinīn","en":"and dwelling in the gardens of al-Firdaws.","de":"und wohnhaft in den Gärten des Firdaws.","open":false}]],[9,[{"ar":"وَنَحْنُ مَعَهُمْ يَا رَبَّ الْعَالَمِينَ","lat":"Wa naḥnu maʿahum yā Rabba-l-ʿĀlamīn","en":"and us together with them, O Lord of the worlds,","de":"und uns mit ihnen, o Herr der Welten,","open":false},{"ar":"وَوَالِدَيْنَا وَمَنْ لَهُمْ حَقٌّ عَلَيْنَا","lat":"Wa wālidaynā wa man lahum ḥaqqun ʿalaynā","en":"and our parents, and whoever has a right over us,","de":"und unsere Eltern und jeden, der ein Recht auf uns hat,","open":false},{"ar":"وَالْمُسْلِمِينَ أَجْمَعِينَ","lat":"Wa-l-Muslimīna ajmaʿīn","en":"and all the Muslims.","de":"und alle Muslime.","open":false},{"ar":"وَارْحَمْنَا إِلَٰهَنَا إِذَا صِرْنَا إِلَى مَا صَارُوا إِلَيْهِ","lat":"Wa-rḥamnā ilāhanā idhā ṣirnā ilā mā ṣārū ilayh","en":"And have mercy on us, our God, when we come to what they have come to.","de":"Und erbarme Dich unser, unser Gott, wenn wir dorthin gelangen, wohin sie gelangt sind.","open":false},{"ar":"اللَّهُمَّ أَنْتَ الْغَنِيُّ وَنَحْنُ الْفُقَرَاءُ","lat":"Allāhumma anta-l-Ghaniyyu wa naḥnu-l-fuqarāʾ","en":"O Allah, You are the Rich, and we are the poor;","de":"O Allah, Du bist der Reiche, und wir sind die Armen;","open":true},{"ar":"الْأَسْرَاءُ بَيْنَ يَدَيْكَ","lat":"Al-asrāʾu bayna yadayk","en":"we are the captives before You.","de":"wir sind die Gefangenen vor Dir.","open":false},{"ar":"إِلَيْكَ تَوَجَّهْنَا","lat":"Ilayka tawajjahnā","en":"To You we turn,","de":"Zu Dir wenden wir uns,","open":false},{"ar":"وَبِبَابِكَ أَنَخْنَا","lat":"Wa bi-bābika anakhnā","en":"and at Your door we have knelt,","de":"und an Deiner Tür haben wir uns niedergelassen,","open":false},{"ar":"وَمِنْ رَحْمَتِكَ سَأَلْنَا","lat":"Wa min raḥmatika saʾalnā","en":"and from Your mercy we have asked,","de":"und um Deine Barmherzigkeit haben wir gebeten,","open":false},{"ar":"وَلِعَفْوِكَ رَجَوْنَا","lat":"Wa li-ʿafwika rajawnā","en":"and for Your pardon we have hoped.","de":"und auf Deine Vergebung haben wir gehofft.","open":false},{"ar":"فَلَا تَرُدَّنَا خَائِبِينَ","lat":"Fa lā taruddanā khāʾibīn","en":"So do not turn us away disappointed.","de":"So weise uns nicht enttäuscht zurück.","open":false},{"ar":"يَا غَافِرَ الذُّنُوبِ إِذَا أُغْلِقَتِ الْأَبْوَابُ","lat":"Yā Ghāfira-dh-dhunūbi idhā ughliqati-l-abwāb","en":"O Forgiver of sins when the doors are closed,","de":"O Vergeber der Sünden, wenn die Türen verschlossen sind,","open":false},{"ar":"يَا مُجِيرَ اللَّاجِئِينَ إِذَا قُطِعَتِ الْأَسْبَابُ","lat":"Yā Mujīra-l-lājiʾīna idhā quṭiʿati-l-asbāb","en":"O Protector of those seeking refuge when all means are cut off:","de":"O Beschützer der Schutzsuchenden, wenn alle Mittel abgeschnitten sind:","open":false},{"ar":"ارْحَمْ ضُعْفَنَا","lat":"Irḥam ḍuʿfanā","en":"Have mercy on our weakness,","de":"Erbarme Dich unserer Schwäche,","open":false},{"ar":"وَاجْبُرْ قُلُوبَنَا","lat":"Wa-jbur qulūbanā","en":"and mend our hearts,","de":"und heile unsere Herzen,","open":false},{"ar":"وَاسْتُرْ عُيُوبَنَا","lat":"Wa-stur ʿuyūbanā","en":"and conceal our faults,","de":"und verhülle unsere Fehler,","open":false},{"ar":"وَاجْعَلْ عَمَلَنَا مَقْبُولًا","lat":"Wa-jʿal ʿamalanā maqbūlā","en":"and make our deeds accepted.","de":"und mache unsere Taten angenommen.","open":false}]],[10,[{"ar":"وَسَعْيَنَا مَشْكُورًا","lat":"Wa saʿyanā mashkūrā","en":"And our effort appreciated,","de":"Und unsere Mühe anerkannt,","open":false},{"ar":"وَتِجَارَتَنَا رَابِحَةً لَنْ تَبُورَ","lat":"Wa tijāratanā rābiḥatan lan tabūr","en":"and our trade profitable, never to fail.","de":"und unseren Handel gewinnbringend, der niemals untergeht.","open":false},{"ar":"وَأَخْرِجْنَا يَا مَوْلَانَا مِنَ الظُّلُمَاتِ إِلَى النُّورِ","lat":"Wa akhrijnā yā Mawlānā mina-ẓ-ẓulumāti ila-n-nūr","en":"And bring us out, O our Master, from darkness into light,","de":"Und führe uns, o unser Herr, aus der Finsternis ins Licht,","open":false},{"ar":"يَا عَزِيزُ يَا غَفُورُ","lat":"Yā ʿAzīzu yā Ghafūr","en":"O Mighty, O Forgiving.","de":"O Erhabener, o Vergebender.","open":false},{"ar":"اللَّهُمَّ أَحْيِنَا مُسْلِمِينَ","lat":"Allāhumma aḥyinā Muslimīn","en":"O Allah, let us live as Muslims,","de":"O Allah, lass uns als Muslime leben,","open":true},{"ar":"وَتَوَفَّنَا مُسْلِمِينَ","lat":"Wa tawaffanā Muslimīn","en":"and let us die as Muslims,","de":"und lass uns als Muslime sterben,","open":false},{"ar":"وَأَلْحِقْنَا بِالصَّالِحِينَ","lat":"Wa alḥiqnā bi-ṣ-ṣāliḥīn","en":"and join us with the righteous,","de":"und vereine uns mit den Rechtschaffenen,","open":false},{"ar":"غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ","lat":"Ghayra khazāyā wa lā maftūnīn","en":"not disgraced, nor tried.","de":"nicht in Schande, noch der Versuchung erlegen.","open":false},{"ar":"اللَّهُمَّ أَعِدْ عَلَيْنَا شَهْرَ الصِّيَامِ وَالْقِيَامِ","lat":"Allāhumma aʿid ʿalaynā shahra-ṣ-ṣiyāmi wa-l-qiyām","en":"O Allah, bring back to us the month of fasting and night-prayer,","de":"O Allah, lass uns den Monat des Fastens und des Nachtgebets wiederkehren,","open":true},{"ar":"وَاجْعَلْ عَامَهُ عَامَ خَيْرٍ وَبَرَكَةٍ وَسَلَامٍ","lat":"Wa-jʿal ʿāmahu ʿāma khayrin wa barakatin wa salām","en":"and make its year a year of goodness, blessing and peace,","de":"und mache sein Jahr zu einem Jahr des Guten, des Segens und des Friedens,","open":false},{"ar":"وَاغْفِرْ لَنَا مَا اقْتَرَفْنَا فِيهِ مِنَ الذُّنُوبِ وَالْآثَامِ","lat":"Wa-ghfir lanā mā-qtarafnā fīhi mina-dh-dhunūbi wa-l-āthām","en":"and forgive us the sins and wrongs we committed in it,","de":"und vergib uns die Sünden und Verfehlungen, die wir darin begangen haben,","open":false},{"ar":"وَتَقَبَّلْ مِنَّا جَمِيعَ مَا قَدَّمْنَا فِيهِ مِنَ الصِّيَامِ وَالْقِيَامِ","lat":"Wa taqabbal minnā jamīʿa mā qaddamnā fīhi mina-ṣ-ṣiyāmi wa-l-qiyām","en":"and accept from us all the fasting and night-prayer we offered in it,","de":"und nimm von uns all das Fasten und Nachtgebet an, das wir darin erbracht haben,","open":false},{"ar":"وَالصَّلَاةِ وَالدُّعَاءِ","lat":"Wa-ṣ-ṣalāti wa-d-duʿāʾ","en":"the prayer and the supplication,","de":"das Gebet und das Bittgebet,","open":false},{"ar":"وَالزَّكَاةِ وَالصَّدَقَاتِ","lat":"Wa-z-zakāti wa-ṣ-ṣadaqāt","en":"and the zakāh and the charities.","de":"und die Zakāh und die Almosen.","open":false},{"ar":"اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ","lat":"Allāhumma-qsim lanā min khashyatika mā taḥūlu bihi baynanā wa bayna maʿṣiyatik","en":"O Allah, grant us such fear of You as will stand between us and disobedience to You,","de":"O Allah, gib uns ein solches Maß an Furcht vor Dir, das zwischen uns und dem Ungehorsam Dir gegenüber steht,","open":true},{"ar":"وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ","lat":"Wa min ṭāʿatika mā tuballighunā bihi jannatak","en":"and such obedience to You as will bring us to Your Paradise.","de":"und ein solches Maß an Gehorsam Dir gegenüber, das uns in Dein Paradies bringt.","open":false}]],[11,[{"ar":"اللَّهُمَّ اجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا","lat":"Allāhumma-jʿal thaʾranā ʿalā man ẓalamanā","en":"O Allah, place our revenge upon whoever wronged us,","de":"O Allah, richte unsere Vergeltung gegen den, der uns Unrecht tat,","open":true},{"ar":"وَانْصُرْنَا عَلَى مَنْ عَادَانَا","lat":"Wa-nṣurnā ʿalā man ʿādānā","en":"and grant us victory over whoever shows us enmity.","de":"und gewähre uns Sieg über den, der uns feindlich gesinnt ist.","open":false},{"ar":"اللَّهُمَّ اخْذُلْ أَعْدَاءَنَا","lat":"Allāhumma-khdhul aʿdāʾanā","en":"O Allah, abandon our enemies,","de":"O Allah, lass unsere Feinde im Stich,","open":true},{"ar":"اللَّهُمَّ اخْذُلْ أَعْدَاءَنَا","lat":"Allāhumma-khdhul aʿdāʾanā","en":"O Allah, abandon our enemies,","de":"O Allah, lass unsere Feinde im Stich,","open":true},{"ar":"وَانْصُرْ مُجَاهِدِينَا","lat":"Wa-nṣur mujāhidīnā","en":"and grant victory to those striving among us.","de":"und gewähre Sieg unseren Kämpfenden.","open":false},{"ar":"وَاحْفَظْ إِخْوَانَنَا الْمُسْلِمِينَ فِي كُلِّ مَكَانٍ","lat":"Wa-ḥfaẓ ikhwānana-l-Muslimīna fī kulli makān","en":"And protect our Muslim brothers everywhere,","de":"Und beschütze unsere muslimischen Brüder überall,","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ لَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا","lat":"Allāhumma lā tajʿali-d-dunyā akbara hamminā","en":"O Allah, do not make the world our greatest concern,","de":"O Allah, mache die Welt nicht zu unserer größten Sorge,","open":true},{"ar":"وَلَا مَبْلَغَ عِلْمِنَا","lat":"Wa lā mablagha ʿilminā","en":"nor the sum of our knowledge,","de":"noch zum Höhepunkt unseres Wissens,","open":false},{"ar":"وَلَا تُسَلِّطْ عَلَيْنَا بِذُنُوبِنَا مَنْ لَا يَخَافُكَ فِينَا وَلَا يَرْحَمُنَا","lat":"Wa lā tusalliṭ ʿalaynā bi-dhunūbinā man lā yakhāfuka fīnā wa lā yarḥamunā","en":"and do not let someone who neither fears You regarding us nor shows us mercy have power over us because of our sins.","de":"und gib wegen unserer Sünden niemandem Macht über uns, der Dich unseretwegen nicht fürchtet und sich unser nicht erbarmt.","open":false},{"ar":"اللَّهُمَّ لَا تَدَعْ لَنَا ذَنْبًا إِلَّا غَفَرْتَهُ","lat":"Allāhumma lā tadaʿ lanā dhanban illā ghafartah","en":"O Allah, do not leave us a sin without forgiving it,","de":"O Allah, lass uns keine Sünde, ohne sie zu vergeben,","open":true},{"ar":"وَلَا هَمًّا إِلَّا فَرَّجْتَهُ","lat":"Wa lā hamman illā farrajtah","en":"nor any worry without relieving it,","de":"noch eine Sorge, ohne sie zu lindern,","open":false},{"ar":"وَلَا دَيْنًا إِلَّا قَضَيْتَهُ","lat":"Wa lā daynan illā qaḍaytah","en":"nor any debt without settling it,","de":"noch eine Schuld, ohne sie zu begleichen,","open":false},{"ar":"وَلَا كَرْبًا إِلَّا نَفَّسْتَهُ","lat":"Wa lā karban illā naffastah","en":"nor any distress without relieving it,","de":"noch eine Bedrängnis, ohne sie zu erleichtern,","open":false},{"ar":"وَلَا مَرِيضًا إِلَّا شَفَيْتَهُ","lat":"Wa lā marīḍan illā shafaytah","en":"nor any sick person without healing him,","de":"noch einen Kranken, ohne ihn zu heilen,","open":false},{"ar":"وَلَا مُبْتَلًى إِلَّا عَافَيْتَهُ","lat":"Wa lā mubtalan illā ʿāfaytah","en":"nor anyone afflicted without restoring him,","de":"noch einen Geprüften, ohne ihm Genesung zu schenken,","open":false},{"ar":"وَلَا غَائِبًا إِلَّا رَدَدْتَهُ","lat":"Wa lā ghāʾiban illā radadtah","en":"nor any absent one without bringing him back.","de":"noch einen Abwesenden, ohne ihn zurückzubringen.","open":false}]],[12,[{"ar":"وَلَا خَيْرًا إِلَّا دَلَلْتَنَا عَلَيْهِ","lat":"Wa lā khayran illā dalaltanā ʿalayh","en":"Nor any good without guiding us to it,","de":"Noch ein Gutes, ohne uns dazu zu leiten,","open":false},{"ar":"وَلَا دَاعِيًا إِلَّا أَجَبْتَهُ","lat":"Wa lā dāʿiyan illā ajabtah","en":"nor any supplicant without answering him,","de":"noch einen Bittenden, ohne ihn zu erhören,","open":false},{"ar":"وَلَا طَالِبًا إِلَّا أَعْطَيْتَهُ","lat":"Wa lā ṭāliban illā aʿṭaytah","en":"nor any seeker without giving him.","de":"noch einen Suchenden, ohne ihm zu geben.","open":false},{"ar":"اللَّهُمَّ لَا مَيِّتًا مِنَ الْمُسْلِمِينَ إِلَّا رَحِمْتَهُ","lat":"Allāhumma lā mayyitan mina-l-Muslimīna illā raḥimtah","en":"O Allah, no deceased among the Muslims without showing him mercy,","de":"O Allah, kein Verstorbener unter den Muslimen, ohne dass Du ihm Barmherzigkeit erweist,","open":true},{"ar":"وَلَا عَدُوًّا لِلْإِسْلَامِ إِلَّا خَذَلْتَهُ","lat":"Wa lā ʿaduwwan li-l-Islāmi illā khadhaltah","en":"nor any enemy of Islam without abandoning him,","de":"noch einen Feind des Islam, ohne ihn im Stich zu lassen,","open":false},{"ar":"وَلَا حَاجَةً مِنْ حَوَائِجِ الدُّنْيَا وَالْآخِرَةِ","lat":"Wa lā ḥājatan min ḥawāʾiji-d-dunyā wa-l-ākhirah","en":"nor any need among the needs of this world and the next,","de":"noch ein Bedürfnis der diesseitigen und jenseitigen Anliegen,","open":false},{"ar":"هِيَ لَكَ رِضًى وَلَنَا فِيهَا صَلَاحٌ إِلَّا أَعَنْتَنَا عَلَى قَضَائِهَا","lat":"Hiya laka riḍan wa lanā fīhā ṣalāḥun illā aʿantanā ʿalā qaḍāʾihā","en":"in which is Your pleasure and our benefit, without helping us fulfill it.","de":"in dem Dein Wohlgefallen und unser Nutzen liegt, ohne dass Du uns bei seiner Erfüllung hilfst.","open":false},{"ar":"اللَّهُمَّ اجْعَلِ اجْتِمَاعَنَا فِي هَٰذِهِ اللَّيْلَةِ اجْتِمَاعًا مَرْحُومًا","lat":"Allāhumma-jʿal-ijtimāʿanā fī hādhihi-l-laylati-jtimāʿan marḥūmā","en":"O Allah, make our gathering on this night a gathering shown mercy,","de":"O Allah, mache unsere Versammlung in dieser Nacht zu einer Versammlung, der Barmherzigkeit erwiesen wird,","open":true},{"ar":"وَتَفَرُّقَنَا تَفَرُّقًا مَعْصُومًا","lat":"Wa tafarruqanā tafarruqan maʿṣūmā","en":"and our parting a protected parting.","de":"und unser Auseinandergehen ein bewahrtes Auseinandergehen.","open":false},{"ar":"وَلَا تَجْعَلْ فِينَا شَقِيًّا وَلَا مَحْرُومًا","lat":"Wa lā tajʿal fīnā shaqiyyan wa lā maḥrūmā","en":"And do not make among us anyone wretched or deprived.","de":"Und mache unter uns niemanden elend oder beraubt.","open":false},{"ar":"اللَّهُمَّ لَا تَجْعَلْ بَيْنَنَا وَبَيْنَكَ فِي رِزْقِنَا أَحَدًا سِوَاكَ","lat":"Allāhumma lā tajʿal baynanā wa baynaka fī rizqinā aḥadan siwāk","en":"O Allah, do not place anyone besides You between us and You regarding our provision,","de":"O Allah, stelle niemanden außer Dir zwischen uns und Dich hinsichtlich unserer Versorgung,","open":true},{"ar":"وَاجْعَلْنَا أَغْنَى خَلْقِكَ بِكَ","lat":"Wa-jʿalnā aghnā khalqika bik","en":"and make us the richest of Your creation through You,","de":"und mache uns zu den Reichsten Deiner Schöpfung durch Dich,","open":false},{"ar":"وَأَفْقَرَ عِبَادِكَ إِلَيْكَ","lat":"Wa afqara ʿibādika ilayk","en":"and the most in need of Your servants towards You.","de":"und zu den Bedürftigsten Deiner Diener Dir gegenüber.","open":false},{"ar":"وَهَبْ لَنَا غِنًى لَا يُطْغِينَا","lat":"Wa hab lanā ghinan lā yuṭghīnā","en":"And grant us riches that do not make us transgress,","de":"Und schenke uns Reichtum, der uns nicht übermütig macht,","open":false},{"ar":"وَصِحَّةً لَا تُلْهِينَا","lat":"Wa ṣiḥḥatan lā tulhīnā","en":"and health that does not distract us.","de":"und Gesundheit, die uns nicht ablenkt.","open":false},{"ar":"وَأَغْنِنَا اللَّهُمَّ عَمَّنْ أَغْنَيْتَهُ عَنَّا","lat":"Wa aghninā Allāhumma ʿamman aghnaytahu ʿannā","en":"And make us independent, O Allah, of whoever You have made independent of us.","de":"Und mache uns, o Allah, unabhängig von dem, den Du von uns unabhängig gemacht hast.","open":false}]],[13,[{"ar":"وَاجْعَلْ آخِرَ كَلَامِنَا مِنَ الدُّنْيَا شَهَادَةَ أَنْ لَا إِلَٰهَ إِلَّا اللَّهُ","lat":"Wa-jʿal ākhira kalāminā mina-d-dunyā shahādata an lā ilāha illā Allāh","en":"And make the last of our words from this world the testimony that there is no god but Allah,","de":"Und mache unser letztes Wort in dieser Welt das Zeugnis, dass es keinen Gott außer Allah gibt,","open":false},{"ar":"وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ","lat":"Wa anna Muḥammadan Rasūlu Allāh","en":"and that Muhammad is the Messenger of Allah.","de":"und dass Muhammad der Gesandte Allahs ist.","open":false},{"ar":"وَتَوَفَّنَا وَأَنْتَ رَاضٍ عَنَّا","lat":"Wa tawaffanā wa anta rāḍin ʿannā","en":"And take our souls while You are pleased with us,","de":"Und nimm unsere Seelen, während Du mit uns zufrieden bist,","open":false},{"ar":"وَاجْعَلْنَا فِي مَوْقِفِ الْقِيَامَةِ مِنَ الْآمِنِينَ","lat":"Wa-jʿalnā fī mawqifi-l-qiyāmati mina-l-āminīn","en":"and make us, in the standing of the Resurrection, among the secure,","de":"und mache uns am Standort der Auferstehung zu den Sicheren,","open":false},{"ar":"مَعَ الَّذِينَ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ","lat":"Maʿa-lladhīna lā khawfun ʿalayhim wa lā hum yaḥzanūn","en":"with those who have no fear, nor do they grieve.","de":"mit denen, die keine Furcht haben und nicht traurig sind.","open":false},{"ar":"اللَّهُمَّ أَصْلِحْ لَنَا دِينَنَا الَّذِي هُوَ عِصْمَةُ أَمْرِنَا","lat":"Allāhumma aṣliḥ lanā dīnana-lladhī huwa ʿiṣmatu amrinā","en":"O Allah, set right for us our religion which is the safeguard of our affairs,","de":"O Allah, ordne für uns unsere Religion, die der Schutz unserer Angelegenheit ist,","open":true},{"ar":"وَدُنْيَانَا الَّتِي فِيهَا مَعَاشُنَا","lat":"Wa dunyānā-llatī fīhā maʿāshunā","en":"and our worldly life in which is our livelihood,","de":"und unser diesseitiges Leben, in dem unser Lebensunterhalt liegt,","open":false},{"ar":"وَآخِرَتَنَا الَّتِي فِيهَا مَعَادُنَا","lat":"Wa ākhiratanā-llatī fīhā maʿādunā","en":"and our Hereafter to which is our return.","de":"und unser Jenseits, zu dem unsere Rückkehr ist.","open":false},{"ar":"وَاجْعَلِ الْحَيَاةَ زِيَادَةً لَنَا فِي كُلِّ خَيْرٍ","lat":"Wa-jʿali-l-ḥayāta ziyādatan lanā fī kulli khayr","en":"And make life an increase for us in every good,","de":"Und mache das Leben für uns zu einer Zunahme an allem Guten,","open":false},{"ar":"وَالْمَوْتَ رَاحَةً لَنَا مِنْ كُلِّ شَرٍّ","lat":"Wa-l-mawta rāḥatan lanā min kulli sharr","en":"and death a rest for us from every evil.","de":"und den Tod zu einer Ruhe für uns von allem Übel.","open":false},{"ar":"اللَّهُمَّ اجْعَلْ خَيْرَ زَمَانِنَا آخِرَهُ","lat":"Allāhumma-jʿal khayra zamāninā ākhirah","en":"O Allah, make the best of our time its end,","de":"O Allah, mache das Beste unserer Zeit ihr Ende,","open":true},{"ar":"وَخَيْرَ أَعْمَالِنَا خَوَاتِيمَهَا","lat":"Wa khayra aʿmālinā khawātīmahā","en":"and the best of our deeds their conclusions,","de":"und das Beste unserer Taten ihren Abschluss,","open":false},{"ar":"وَخَيْرَ أَيَّامِنَا يَوْمَ لِقَائِكَ","lat":"Wa khayra ayyāminā yawma liqāʾik","en":"and the best of our days the day we meet You,","de":"und den besten unserer Tage den Tag unserer Begegnung mit Dir,","open":false},{"ar":"يَا رَبَّ الْعَالَمِينَ","lat":"Yā Rabba-l-ʿĀlamīn","en":"O Lord of the worlds.","de":"O Herr der Welten.","open":false},{"ar":"رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ","lat":"Rabbanā ẓalamnā anfusanā wa in lam taghfir lanā wa tarḥamnā lanakūnanna mina-l-khāsirīn","en":"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.","de":"Unser Herr, wir haben uns selbst Unrecht getan, und wenn Du uns nicht vergibst und Dich unser erbarmst, werden wir gewiss zu den Verlierern gehören.","open":false},{"ar":"إِلَٰهَنَا وَمَوْلَانَا","lat":"Ilāhanā wa Mawlānā","en":"Our God and our Master.","de":"Unser Gott und unser Herr.","open":false}]],[14,[{"ar":"حَرَّرْنَا خَتْمَةَ كِتَابِكَ","lat":"Ḥarrarnā khatmata kitābik","en":"We have completed the finishing of Your Book.","de":"Wir haben die Vollendung Deines Buches abgeschlossen.","open":false},{"ar":"فَاللَّهُمَّ تَقَبَّلْ هَٰذِهِ مِنَّا","lat":"Fa-Allāhumma taqabbal hādhihi minnā","en":"So, O Allah, accept this from us,","de":"So, o Allah, nimm dies von uns an,","open":true},{"ar":"اللَّهُمَّ تَقَبَّلْ هَٰذِهِ مِنَّا","lat":"Allāhumma taqabbal hādhihi minnā","en":"O Allah, accept this from us,","de":"O Allah, nimm dies von uns an,","open":true},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ أَغْنِنَا بِحَلَالِكَ عَنْ حَرَامِكَ","lat":"Allāhumma aghninā bi-ḥalālika ʿan ḥarāmik","en":"O Allah, make us independent through what You have made lawful from what You have made unlawful,","de":"O Allah, mache uns durch Dein Erlaubtes unabhängig von Deinem Verbotenen,","open":true},{"ar":"وَبِفَضْلِكَ عَمَّنْ سِوَاكَ","lat":"Wa bi-faḍlika ʿamman siwāk","en":"and through Your grace independent of all besides You.","de":"und durch Deine Gnade unabhängig von allen außer Dir.","open":false},{"ar":"اللَّهُمَّ لَا تَفْتِنَّا فِي حَيَاتِنَا","lat":"Allāhumma lā taftinnā fī ḥayātinā","en":"O Allah, do not try us in our life,","de":"O Allah, prüfe uns nicht in unserem Leben,","open":true},{"ar":"اللَّهُمَّ لَا تَفْتِنَّا فِي حَيَاتِنَا","lat":"Allāhumma lā taftinnā fī ḥayātinā","en":"O Allah, do not try us in our life,","de":"O Allah, prüfe uns nicht in unserem Leben,","open":true},{"ar":"اللَّهُمَّ تَوَفَّنَا وَأَنْتَ رَاضٍ عَنَّا","lat":"Allāhumma tawaffanā wa anta rāḍin ʿannā","en":"O Allah, cause us to die while You are pleased with us,","de":"O Allah, lass uns sterben, während Du mit uns zufrieden bist,","open":true},{"ar":"اللَّهُمَّ اسْتُرْ عَوْرَاتِنَا","lat":"Allāhumma-stur ʿawrātinā","en":"O Allah, conceal our faults,","de":"O Allah, verhülle unsere Blößen,","open":true},{"ar":"وَآمِنْ رَوْعَاتِنَا","lat":"Wa āmin rawʿātinā","en":"and calm our fears.","de":"und beruhige unsere Ängste.","open":false},{"ar":"اللَّهُمَّ اسْتُرْ عَوْرَاتِنَا","lat":"Allāhumma-stur ʿawrātinā","en":"O Allah, conceal our faults,","de":"O Allah, verhülle unsere Blößen,","open":true},{"ar":"وَآمِنْ رَوْعَاتِنَا","lat":"Wa āmin rawʿātinā","en":"and calm our fears.","de":"und beruhige unsere Ängste.","open":false},{"ar":"وَاغْفِرْ زَلَّاتِنَا","lat":"Wa-ghfir zallātinā","en":"And forgive our slips,","de":"Und vergib unsere Fehltritte,","open":false},{"ar":"وَأَصْلِحْ أَوْلَادَنَا","lat":"Wa aṣliḥ awlādanā","en":"and set right our children,","de":"und bessere unsere Kinder,","open":false},{"ar":"وَاسْتُرْ عَلَى نِسَائِنَا","lat":"Wa-stur ʿalā nisāʾinā","en":"and cover our women,","de":"und beschütze unsere Frauen,","open":false},{"ar":"وَاحْفَظْ جَمِيعَ إِخْوَانِنَا الْمُسْلِمِينَ","lat":"Wa-ḥfaẓ jamīʿa ikhwānina-l-Muslimīn","en":"and protect all our Muslim brothers.","de":"und beschütze alle unsere muslimischen Brüder.","open":false}]],[15,[{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ فِي هَٰذِهِ السَّاعَةِ الْمُبَارَكَةِ الْكَرِيمَةِ","lat":"Allāhumma fī hādhihi-s-sāʿati-l-mubārakati-l-karīmah","en":"O Allah, in this blessed and noble hour,","de":"O Allah, in dieser gesegneten und edlen Stunde,","open":true},{"ar":"وَفِي هَٰذِهِ اللَّيْلَةِ الْمُبَارَكَةِ","lat":"Wa fī hādhihi-l-laylati-l-mubārakah","en":"and in this blessed night,","de":"und in dieser gesegneten Nacht,","open":false},{"ar":"أَعْتِقْ رِقَابَنَا مِنَ النَّارِ","lat":"Aʿtiq riqābanā mina-n-nār","en":"free our necks from the Fire.","de":"befreie unsere Nacken vom Feuer.","open":false},{"ar":"اللَّهُمَّ أَعْتِقْ رِقَابَنَا مِنَ النَّارِ","lat":"Allāhumma aʿtiq riqābanā mina-n-nār","en":"O Allah, free our necks from the Fire,","de":"O Allah, befreie unsere Nacken vom Feuer,","open":true},{"ar":"يَا مَوْلَانَا وَيَا أَمَلَنَا أَعْتِقْ رِقَابَنَا مِنَ النَّارِ","lat":"Yā Mawlānā wa yā amalanā aʿtiq riqābanā mina-n-nār","en":"O our Master and our Hope, free our necks from the Fire.","de":"O unser Herr und unsere Hoffnung, befreie unsere Nacken vom Feuer.","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"إِلَٰهَنَا وَمَوْلَانَا","lat":"Ilāhanā wa Mawlānā","en":"Our God and our Master,","de":"Unser Gott und unser Herr,","open":false},{"ar":"مَنْ لَنَا إِذَا طُرِدْنَا مِنْ بَابِكَ","lat":"Man lanā idhā ṭuridnā min bābik","en":"who do we have if we are turned away from Your door?","de":"wen haben wir, wenn wir von Deiner Tür verstoßen werden?","open":false},{"ar":"إِلَٰهَنَا وَمَوْلَانَا","lat":"Ilāhanā wa Mawlānā","en":"Our God and our Master,","de":"Unser Gott und unser Herr,","open":false},{"ar":"أَنْتَ رَجَاؤُنَا وَأَمَلُنَا","lat":"Anta rajāʾunā wa amalunā","en":"You are our hope and our aspiration.","de":"Du bist unsere Hoffnung und unser Verlangen.","open":false},{"ar":"يَا رَجَاءَنَا وَيَا أَمَلَنَا لَا تَرُدَّنَا خَائِبِينَ","lat":"Yā rajāʾanā wa yā amalanā lā taruddanā khāʾibīn","en":"O our hope and our aspiration, do not turn us away disappointed.","de":"O unsere Hoffnung und unser Verlangen, weise uns nicht enttäuscht zurück.","open":false},{"ar":"اللَّهُمَّ تَقَبَّلْ مِنَّا مَا عَمِلْنَا فِي هَٰذَا الشَّهْرِ الْكَرِيمِ","lat":"Allāhumma taqabbal minnā mā ʿamilnā fī hādhā-sh-shahri-l-karīm","en":"O Allah, accept from us what we have done in this noble month.","de":"O Allah, nimm von uns an, was wir in diesem edlen Monat getan haben.","open":true},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ إِنَّا وَقَفْنَا بِبَابِكَ خَاضِعِينَ خَاشِعِينَ","lat":"Allāhumma innā waqafnā bi-bābika khāḍiʿīna khāshiʿīn","en":"O Allah, we have stood at Your door, submissive and humble,","de":"O Allah, wir stehen an Deiner Tür, demütig und ergeben,","open":true},{"ar":"نَرْجُو رَحْمَتَكَ وَنَخْشَى عَذَابَكَ","lat":"Narjū raḥmataka wa nakhshā ʿadhābak","en":"hoping for Your mercy and fearing Your punishment.","de":"wir erhoffen Deine Barmherzigkeit und fürchten Deine Strafe.","open":false}]],[16,[{"ar":"اللَّهُمَّ ارْحَمْ ضُعَفَاءَنَا","lat":"Allāhumma-rḥam ḍuʿafāʾanā","en":"O Allah, have mercy on our weak ones,","de":"O Allah, erbarme Dich unserer Schwachen,","open":true},{"ar":"اللَّهُمَّ ارْحَمْ ضُعَفَاءَنَا","lat":"Allāhumma-rḥam ḍuʿafāʾanā","en":"O Allah, have mercy on our weak ones,","de":"O Allah, erbarme Dich unserer Schwachen,","open":true},{"ar":"اللَّهُمَّ ارْحَمْ فَزَعَنَا","lat":"Allāhumma-rḥam fazaʿanā","en":"O Allah, have mercy on our fright,","de":"O Allah, erbarme Dich unserer Angst,","open":true},{"ar":"اللَّهُمَّ ارْحَمْ تَضَرُّعَنَا","lat":"Allāhumma-rḥam taḍarruʿanā","en":"O Allah, have mercy on our humble pleading,","de":"O Allah, erbarme Dich unseres demütigen Flehens,","open":true},{"ar":"اللَّهُمَّ ارْحَمْ مَسْكَنَتَنَا","lat":"Allāhumma-rḥam maskanatanā","en":"O Allah, have mercy on our destitution,","de":"O Allah, erbarme Dich unserer Bedürftigkeit,","open":true},{"ar":"اللَّهُمَّ ارْحَمْ تَوْبَتَنَا","lat":"Allāhumma-rḥam tawbatanā","en":"O Allah, have mercy on our repentance.","de":"O Allah, erbarme Dich unserer Reue.","open":true},{"ar":"اللَّهُمَّ انْظُرْ إِلَيْنَا بِرَحْمَتِكَ","lat":"Allāhumma-nẓur ilaynā bi-raḥmatik","en":"O Allah, look upon us with Your mercy,","de":"O Allah, blicke mit Deiner Barmherzigkeit auf uns,","open":true},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"فَإِنْ تَرَكْتَنَا فَلَا حَوْلَ لَنَا وَلَا قُوَّةَ إِلَّا بِكَ","lat":"Fa-in taraktanā fa-lā ḥawla lanā wa lā qūwwata illā bik","en":"For if You leave us, we have no power nor strength except through You.","de":"Denn wenn Du uns verlässt, haben wir keine Macht noch Kraft außer durch Dich.","open":false},{"ar":"اللَّهُمَّ يَا مَنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ","lat":"Allāhumma yā man khalaqa-s-samāwāti wa-l-arḍ","en":"O Allah, O He who created the heavens and the earth,","de":"O Allah, o Der die Himmel und die Erde erschuf,","open":true},{"ar":"وَيَا مَنْ بِيَدِهِ الْأَمْرُ كُلُّهُ","lat":"Wa yā man bi-yadihi-l-amru kulluh","en":"and O He in whose hand is all command,","de":"und o Der, in dessen Hand alle Macht liegt,","open":false},{"ar":"وَيَا مَنْ إِذَا أَرَادَ شَيْئًا قَالَ لَهُ كُنْ فَيَكُونُ","lat":"Wa yā man idhā arāda shayʾan qāla lahu kun fa-yakūn","en":"and O He who, when He wills a thing, says to it 'Be,' and it is.","de":"und o Der, der, wenn Er etwas will, zu ihm sagt 'Sei', und es ist.","open":false},{"ar":"اللَّهُمَّ لَا تَرُدَّنِي وَإِخْوَانِي مِنْ بَابِكَ مَحْرُومِينَ","lat":"Allāhumma lā taruddanī wa ikhwānī min bābika maḥrūmīn","en":"O Allah, do not turn me and my brothers away from Your door deprived,","de":"O Allah, weise mich und meine Brüder nicht beraubt von Deiner Tür zurück,","open":true},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ مُنَّ عَلَيْنَا بِتَوْبَةٍ قَبْلَ الْمَمَاتِ","lat":"Allāhumma munna ʿalaynā bi-tawbatin qabla-l-mamāt","en":"O Allah, favor us with repentance before death,","de":"O Allah, begnade uns mit Reue vor dem Tod,","open":true},{"ar":"اللَّهُمَّ مُنَّ عَلَيْنَا بِتَوْبَةٍ قَبْلَ الْمَمَاتِ","lat":"Allāhumma munna ʿalaynā bi-tawbatin qabla-l-mamāt","en":"O Allah, favor us with repentance before death,","de":"O Allah, begnade uns mit Reue vor dem Tod,","open":true},{"ar":"وَارْحَمْنَا عِنْدَ الْمَمَاتِ","lat":"Wa-rḥamnā ʿinda-l-mamāt","en":"and have mercy on us at death.","de":"und erbarme Dich unser beim Tod.","open":false}]],[17,[{"ar":"اللَّهُمَّ ارْحَمْنَا إِذَا جَاءَتْ سَكَرَاتُ الْمَوْتِ","lat":"Allāhumma-rḥamnā idhā jāʾat sakarātu-l-mawt","en":"O Allah, have mercy on us when the agonies of death come,","de":"O Allah, erbarme Dich unser, wenn die Todesqualen kommen,","open":true},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"غُفْرَانَكَ غُفْرَانَكَ","lat":"Ghufrānaka ghufrānak","en":"Your forgiveness, Your forgiveness,","de":"Deine Vergebung, Deine Vergebung,","open":false},{"ar":"لَا إِلَٰهَ إِلَّا أَنْتَ","lat":"Lā ilāha illā ant","en":"there is no god but You.","de":"es gibt keinen Gott außer Dir.","open":false},{"ar":"لَا إِلَٰهَ إِلَّا اللَّهُ","lat":"Lā ilāha illā Allāh","en":"There is no god but Allah,","de":"Es gibt keinen Gott außer Allah,","open":false},{"ar":"ذُو الْمُلْكِ وَالْقُوَّةِ وَالْجَبَرُوتِ","lat":"Dhu-l-Mulki wa-l-Quwwati wa-l-Jabarūt","en":"Possessor of Sovereignty, Power and Omnipotence.","de":"Besitzer der Herrschaft, der Macht und der Allgewalt.","open":false},{"ar":"اللَّهُمَّ ارْحَمْنَا إِذَا تَطَايَرَتِ الصُّحُفُ وَخَفَّتِ الْمَوَازِينُ","lat":"Allāhumma-rḥamnā idhā taṭāyarati-ṣ-ṣuḥufu wa khaffati-l-mawāzīn","en":"O Allah, have mercy on us when the pages fly about and the scales grow light,","de":"O Allah, erbarme Dich unser, wenn die Schriften umherfliegen und die Waagschalen leicht werden,","open":true},{"ar":"اللَّهُمَّ ارْحَمْنَا إِذَا نُصِبَ الصِّرَاطُ","lat":"Allāhumma-rḥamnā idhā nuṣiba-ṣ-ṣirāṭ","en":"O Allah, have mercy on us when the Bridge is set up,","de":"O Allah, erbarme Dich unser, wenn die Brücke errichtet wird,","open":true},{"ar":"اللَّهُمَّ ارْحَمْنَا إِذَا زَفَرَتِ النَّارُ","lat":"Allāhumma-rḥamnā idhā zafarati-n-nār","en":"O Allah, have mercy on us when the Fire roars.","de":"O Allah, erbarme Dich unser, wenn das Feuer brüllt.","open":true},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"يَا سَامِعَ الصَّوْتِ","lat":"Yā Sāmiʿa-ṣ-ṣawt","en":"O Hearer of every sound,","de":"O Hörer jeder Stimme,","open":false},{"ar":"وَيَا سَابِقَ الْفَوْتِ","lat":"Wa yā Sābiqa-l-fawt","en":"and O One from whom nothing escapes,","de":"und o Der, dem nichts entgeht,","open":false},{"ar":"وَيَا كَاسِيَ الْعِظَامِ لَحْمًا بَعْدَ الْمَوْتِ","lat":"Wa yā Kāsiya-l-ʿiẓāma laḥman baʿda-l-mawt","en":"and O Clother of the bones with flesh after death:","de":"und o Der die Knochen nach dem Tod wieder mit Fleisch bekleidet:","open":false},{"ar":"اللَّهُمَّ إِنَّ أَجْسَادَنَا عَلَى النَّارِ لَا تَقْوَى","lat":"Allāhumma inna ajsādanā ʿala-n-nāri lā taqwā","en":"O Allah, indeed our bodies cannot withstand the Fire,","de":"O Allah, unsere Körper können dem Feuer nicht standhalten,","open":true},{"ar":"فَلَا تُعَذِّبْنَا بِمَا عَمِلْنَا","lat":"Fa lā tuʿadhdhibnā bimā ʿamilnā","en":"so do not punish us for what we have done.","de":"so bestrafe uns nicht für das, was wir getan haben.","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ ارْتَفَعَتِ الْأَصْوَاتُ بِالْبُكَاءِ وَالنَّحِيبِ","lat":"Allāhumma-rtafaʿati-l-aṣwātu bi-l-bukāʾi wa-n-naḥīb","en":"O Allah, voices have risen in weeping and wailing.","de":"O Allah, die Stimmen haben sich im Weinen und Klagen erhoben.","open":true}]],[18,[{"ar":"فَلَا تَرُدَّنَا مِنْ بَابِكَ يَا أَرْحَمَ الرَّاحِمِينَ","lat":"Fa lā taruddanā min bābika yā Arḥama-r-Rāḥimīn","en":"So do not turn us away from Your door, O Most Merciful of the merciful,","de":"So weise uns nicht von Deiner Tür ab, o Barmherzigster der Barmherzigen,","open":false},{"ar":"اللَّهُمَّ لَا تَرُدَّنَا مِنْ بَابِكَ يَا أَرْحَمَ الرَّاحِمِينَ","lat":"Allāhumma lā taruddanā min bābika yā Arḥama-r-Rāḥimīn","en":"O Allah, do not turn us away from Your door, O Most Merciful of the merciful.","de":"O Allah, weise uns nicht von Deiner Tür ab, o Barmherzigster der Barmherzigen.","open":true},{"ar":"اللَّهُمَّ تَقَبَّلْ مِنَّا أَعْمَالَنَا","lat":"Allāhumma taqabbal minnā aʿmālanā","en":"O Allah, accept our deeds from us,","de":"O Allah, nimm unsere Taten von uns an,","open":true},{"ar":"وَاجْعَلْهَا خَالِصَةً لِوَجْهِكَ الْكَرِيمِ","lat":"Wa-jʿalhā khāliṣatan li-wajhika-l-karīm","en":"and make them sincere for Your noble Face.","de":"und mache sie aufrichtig für Dein edles Antlitz.","open":false},{"ar":"اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَ شَهْرِ رَمَضَانَ","lat":"Allāhumma lā taḥrimnā ajra shahri Ramaḍān","en":"O Allah, do not deprive us of the reward of the month of Ramaḍān,","de":"O Allah, beraube uns nicht des Lohnes des Monats Ramaḍān,","open":true},{"ar":"اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَ شَهْرِنَا هَٰذَا","lat":"Allāhumma lā taḥrimnā ajra shahrinā hādhā","en":"O Allah, do not deprive us of the reward of this our month,","de":"O Allah, beraube uns nicht des Lohnes dieses unseres Monats,","open":true},{"ar":"وَلَا تَفْتِنَّا بَعْدَهُ","lat":"Wa lā taftinnā baʿdah","en":"and do not try us after it.","de":"und prüfe uns nicht danach.","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"وَصَبِّرْنَا عَلَى طَاعَتِكَ وَعَلَى الصَّلَاةِ","lat":"Wa ṣabbirnā ʿalā ṭāʿatika wa ʿala-ṣ-ṣalāh","en":"And give us patience in obedience to You and in prayer,","de":"Und gib uns Geduld im Gehorsam Dir gegenüber und im Gebet,","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ اغْفِرْ لَنَا أَجْمَعِينَ","lat":"Allāhumma-ghfir lanā ajmaʿīn","en":"O Allah, forgive us all,","de":"O Allah, vergib uns allen,","open":true},{"ar":"وَهَبِ الْمُسِيئِينَ مِنَّا لِلْمُسْلِمِينَ","lat":"Wa habi-l-musīʾīna minnā li-l-Muslimīn","en":"and grant the wrongdoers among us to the Muslims.","de":"und schenke die Übeltäter unter uns den Muslimen.","open":false},{"ar":"اللَّهُمَّ اجْعَلْ لَنَا فِي كُلِّ حَرْفٍ قَرَأْنَاهُ مِنْ كِتَابِكَ حَسَنَاتٍ","lat":"Allāhumma-jʿal lanā fī kulli ḥarfin qaraʾnāhu min kitābika ḥasanāt","en":"O Allah, grant us good deeds for every letter we have recited from Your Book.","de":"O Allah, gewähre uns für jeden Buchstaben, den wir aus Deinem Buch gelesen haben, gute Taten.","open":true},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ جَمِّلْنَا بِالْقُرْآنِ","lat":"Allāhumma jammilnā bi-l-Qurʾān","en":"O Allah, beautify us with the Qurʾān,","de":"O Allah, schmücke uns mit dem Qurʾān,","open":true},{"ar":"اللَّهُمَّ جَمِّلْنَا بِالْقُرْآنِ","lat":"Allāhumma jammilnā bi-l-Qurʾān","en":"O Allah, beautify us with the Qurʾān,","de":"O Allah, schmücke uns mit dem Qurʾān,","open":true}]],[19,[{"ar":"وَنَوِّرْنَا بِالْإِيمَانِ","lat":"Wa nawwirnā bi-l-īmān","en":"and illuminate us with faith.","de":"und erleuchte uns mit dem Glauben.","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ فِي هَٰذِهِ اللَّيْلَةِ الْمُبَارَكَةِ","lat":"Allāhumma fī hādhihi-l-laylati-l-mubārakah","en":"O Allah, in this blessed night,","de":"O Allah, in dieser gesegneten Nacht,","open":true},{"ar":"وَفِي هَٰذَا الْمَسْجِدِ الْمُبَارَكِ","lat":"Wa fī hādhā-l-masjidi-l-mubārak","en":"and in this blessed mosque,","de":"und in dieser gesegneten Moschee,","open":false},{"ar":"لَا يَنْفَضُّ هَٰذَا الْجَمْعُ إِلَّا بِذَنْبٍ مَغْفُورٍ","lat":"Lā yanfaḍḍu hādhā-l-jamʿu illā bi-dhanbin maghfūr","en":"may this gathering not disperse except with sins forgiven.","de":"möge sich diese Versammlung nicht auflösen, ohne dass die Sünden vergeben sind.","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ اقْذِفْ فِي قُلُوبِنَا الْعِلْمَ وَالْيَقِينَ","lat":"Allāhumma-qdhif fī qulūbinā-l-ʿilma wa-l-yaqīn","en":"O Allah, cast into our hearts knowledge and certainty,","de":"O Allah, wirf in unsere Herzen Wissen und Gewissheit,","open":true},{"ar":"وَتَوَفَّنَا وَأَنْتَ رَاضٍ عَنَّا","lat":"Wa tawaffanā wa anta rāḍin ʿannā","en":"and take our souls while You are pleased with us.","de":"und nimm unsere Seelen, während Du mit uns zufrieden bist.","open":false},{"ar":"يَا أَرْحَمَ الرَّاحِمِينَ","lat":"Yā Arḥama-r-Rāḥimīn","en":"O Most Merciful of the merciful.","de":"O Barmherzigster der Barmherzigen.","open":false},{"ar":"وَآتِنَا فِي الدُّنْيَا حَسَنَةً","lat":"Wa ātinā fi-d-dunyā ḥasanah","en":"And grant us good in this world,","de":"Und gib uns Gutes im Diesseits,","open":false},{"ar":"وَفِي الْآخِرَةِ حَسَنَةً","lat":"Wa fi-l-ākhirati ḥasanah","en":"and good in the Hereafter,","de":"und Gutes im Jenseits,","open":false},{"ar":"وَقِنَا عَذَابَ النَّارِ","lat":"Wa qinā ʿadhāba-n-nār","en":"and protect us from the punishment of the Fire.","de":"und bewahre uns vor der Strafe des Feuers.","open":false},{"ar":"وَأَدْخِلْنَا الْجَنَّةَ مَعَ الْأَبْرَارِ","lat":"Wa adkhilna-l-jannata maʿa-l-abrār","en":"And admit us into Paradise with the righteous,","de":"Und lass uns mit den Rechtschaffenen ins Paradies eintreten,","open":false},{"ar":"بِرَحْمَتِكَ يَا عَزِيزُ يَا غَفَّارُ","lat":"Bi-raḥmatika yā ʿAzīzu yā Ghaffār","en":"by Your mercy, O Mighty, O Much-Forgiving.","de":"durch Deine Barmherzigkeit, o Erhabener, o Allvergebender.","open":false},{"ar":"اللَّهُمَّ إِنَّا اشْتَقْنَا لِرُؤْيَةِ حَبِيبِنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ","lat":"Allāhumma inna-shtaqnā li-ruʾyati ḥabībinā Muḥammadin ṣallā Allāhu ʿalayhi wa sallam","en":"O Allah, we long to see our beloved Muhammad, may Allah bless him and grant him peace,","de":"O Allah, wir sehnen uns danach, unseren geliebten Muhammad zu sehen, Allahs Segen und Friede seien auf ihm,","open":true},{"ar":"فَاحْشُرْنَا اللَّهُمَّ مَعَهُ","lat":"Fa-ḥshurnā Allāhumma maʿah","en":"so gather us, O Allah, with him,","de":"so versammle uns, o Allah, mit ihm,","open":false},{"ar":"وَأَوْرِدْنَا حَوْضَهُ","lat":"Wa awridnā ḥawḍah","en":"and bring us to his Pool.","de":"und führe uns zu seinem Becken.","open":false}]],[20,[{"ar":"اللَّهُمَّ خُذْ بِأَيْدِينَا فِي يَدِهِ إِلَى جَنَّاتِ النَّعِيمِ","lat":"Allāhumma khudh bi-aydīnā fī yadihi ilā jannāti-n-naʿīm","en":"O Allah, take our hands in his hand to the gardens of bliss,","de":"O Allah, nimm unsere Hände in seine Hand zu den Gärten der Wonne,","open":true},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ إِنَّا نَشْتَاقُ إِلَى صَحَابَتِهِ الْمُكَرَّمِينَ","lat":"Allāhumma innā nashtāqu ilā ṣaḥābatihi-l-mukarramīn","en":"O Allah, we long for his honored companions,","de":"O Allah, wir sehnen uns nach seinen geehrten Gefährten,","open":true},{"ar":"فَيَا رَبَّنَا لَا تَحْرِمْنَا أَجْرَهُمْ","lat":"Fa yā Rabbanā lā taḥrimnā ajrahum","en":"so, our Lord, do not deprive us of their reward,","de":"so, unser Herr, beraube uns nicht ihres Lohnes,","open":false},{"ar":"وَاحْشُرْنَا مَعَهُمْ","lat":"Wa-ḥshurnā maʿahum","en":"and gather us with them.","de":"und versammle uns mit ihnen.","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ إِنَّا نُشْهِدُكَ أَنَّنَا نُحِبُّهُمْ","lat":"Allāhumma innā nushhiduka annanā nuḥibbuhum","en":"O Allah, we call You to witness that we love them,","de":"O Allah, wir rufen Dich zum Zeugen, dass wir sie lieben,","open":true},{"ar":"وَنُحِبُّ مَنْ يُحِبُّهُمْ","lat":"Wa nuḥibbu man yuḥibbuhum","en":"and we love whoever loves them.","de":"und wir lieben, wer sie liebt.","open":false},{"ar":"فَاحْشُرْنَا وَمَنْ أَحَبَّهُمْ مَعَهُمْ يَا رَبَّ الْعَالَمِينَ","lat":"Fa-ḥshurnā wa man aḥabbahum maʿahum yā Rabba-l-ʿĀlamīn","en":"So gather us and whoever loves them together with them, O Lord of the worlds.","de":"So versammle uns und wer sie liebt mit ihnen, o Herr der Welten.","open":false},{"ar":"وَعَادِ اللَّهُمَّ مَنْ أَبْغَضَهُمْ","lat":"Wa ʿādi Allāhumma man abghaḍahum","en":"And be, O Allah, an enemy to whoever hates them,","de":"Und sei, o Allah, ein Feind dessen, der sie hasst,","open":false},{"ar":"وَالْعَنِ اللَّهُمَّ مَنْ لَعَنَهُمْ","lat":"Wa-l-ʿani Allāhumma man laʿanahum","en":"and curse, O Allah, whoever curses them.","de":"und verfluche, o Allah, wer sie verflucht.","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ قَيِّضْ لَنَا خِيَارَنَا بِنُصْرَةِ الْإِسْلَامِ وَالْمُسْلِمِينَ","lat":"Allāhumma qayyiḍ lanā khiyāranā bi-nuṣrati-l-Islāmi wa-l-Muslimīn","en":"O Allah, appoint for us our best people for the support of Islam and the Muslims,","de":"O Allah, bestimme uns unsere Besten zur Unterstützung des Islam und der Muslime,","open":true},{"ar":"اللَّهُمَّ قَيِّضْ لَنَا خِيَارَنَا بِنُصْرَةِ الْإِسْلَامِ وَالْمُسْلِمِينَ","lat":"Allāhumma qayyiḍ lanā khiyāranā bi-nuṣrati-l-Islāmi wa-l-Muslimīn","en":"O Allah, appoint for us our best people for the support of Islam and the Muslims,","de":"O Allah, bestimme uns unsere Besten zur Unterstützung des Islam und der Muslime,","open":true},{"ar":"فِي كُلِّ مَكَانٍ","lat":"Fī kulli makān","en":"in every place.","de":"an jedem Ort.","open":false}]],[21,[{"ar":"اللَّهُمَّ آمِنَّا فِي وَقْتِنَا هَٰذَا","lat":"Allāhumma āminnā fī waqtinā hādhā","en":"O Allah, grant us security in this our time,","de":"O Allah, gewähre uns Sicherheit in dieser unserer Zeit,","open":true},{"ar":"وَسَائِرَ بِلَادِ الْمُسْلِمِينَ","lat":"Wa sāʾira bilādi-l-Muslimīn","en":"and the rest of the lands of the Muslims.","de":"und die übrigen Länder der Muslime.","open":false},{"ar":"وَأَصْلِحِ اللَّهُمَّ إِمَامَنَا لِمَا تُحِبُّهُ وَتَرْضَاهُ","lat":"Wa aṣliḥi Allāhumma imāmanā limā tuḥibbuhu wa tarḍāh","en":"And set right, O Allah, our leader for what You love and are pleased with,","de":"Und richte, o Allah, unseren Führer nach dem, was Du liebst und womit Du zufrieden bist,","open":false},{"ar":"وَأَصْلِحِ اللَّهُمَّ أُمَرَاءَهُ وَوُزَرَاءَهُ وَعُلَمَاءَهُ لِمَا فِيهِ خَيْرُ الْإِسْلَامِ وَالْمُسْلِمِينَ","lat":"Wa aṣliḥi Allāhumma umarāʾahu wa wuzarāʾahu wa ʿulamāʾahu limā fīhi khayru-l-Islāmi wa-l-Muslimīn","en":"and set right, O Allah, its leaders, its ministers and its scholars for what is best for Islam and the Muslims.","de":"und richte, o Allah, seine Befehlshaber, seine Minister und seine Gelehrten nach dem, was dem Islam und den Muslimen am besten dient.","open":false},{"ar":"بَارِكْ لَنَا فِي عُلَمَائِنَا","lat":"Bārik lanā fī ʿulamāʾinā","en":"Bless us in our scholars,","de":"Segne uns in unseren Gelehrten,","open":false},{"ar":"اللَّهُمَّ بَارِكْ لَنَا فِي عُلَمَائِنَا","lat":"Allāhumma bārik lanā fī ʿulamāʾinā","en":"O Allah, bless us in our scholars,","de":"O Allah, segne uns in unseren Gelehrten,","open":true},{"ar":"وَاحْفَظْهُمُ اللَّهُمَّ لَنَا","lat":"Wa-ḥfaẓhumu Allāhumma lanā","en":"and preserve them, O Allah, for us,","de":"und bewahre sie uns, o Allah,","open":false},{"ar":"وَقَرِّرِ اللَّهُمَّ فِي الْخَيْرِ أَعْمَالَهُمْ وَأَعْمَارَهُمْ","lat":"Wa qarriri Allāhumma fi-l-khayri aʿmālahum wa aʿmārahum","en":"and establish, O Allah, their deeds and their lifespans in goodness.","de":"und festige, o Allah, in Güte ihre Taten und ihre Lebenszeit.","open":false},{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"اللَّهُمَّ وَفِّقْ طَلَبَةَ الْعِلْمِ فِي بِلَادِنَا لِمَا فِيهِ خَيْرُهُمْ وَصَلَاحُهُمْ","lat":"Allāhumma waffiq ṭalabata-l-ʿilmi fī bilādinā limā fīhi khayruhum wa ṣalāḥuhum","en":"O Allah, grant success to the students of knowledge in our lands for what is good and right for them,","de":"O Allah, gewähre den Wissenssuchenden in unseren Ländern Erfolg zu dem, was ihnen gut und recht ist,","open":true},{"ar":"فِي دِينِهِمْ وَدُنْيَاهُمْ وَآخِرَتِهِمْ","lat":"Fī dīnihim wa dunyāhum wa ākhiratihim","en":"in their religion, their worldly life and their Hereafter.","de":"in ihrer Religion, ihrem Diesseits und ihrem Jenseits.","open":false},{"ar":"اهْدِ اللَّهُمَّ شَبَابَنَا","lat":"Ihdi Allāhumma shabābanā","en":"Guide, O Allah, our youth,","de":"Leite, o Allah, unsere Jugend,","open":false},{"ar":"اللَّهُمَّ اهْدِ شَبَابَنَا","lat":"Allāhumma-hdi shabābanā","en":"O Allah, guide our youth,","de":"O Allah, leite unsere Jugend,","open":true},{"ar":"اللَّهُمَّ اهْدِ شَبَابَنَا","lat":"Allāhumma-hdi shabābanā","en":"O Allah, guide our youth,","de":"O Allah, leite unsere Jugend,","open":true},{"ar":"وَاحْفَظْ نِسَاءَنَا","lat":"Wa-ḥfaẓ nisāʾanā","en":"and protect our women,","de":"und beschütze unsere Frauen,","open":false},{"ar":"وَبَنَاتِنَا","lat":"Wa banātinā","en":"and our daughters.","de":"und unsere Töchter.","open":false}]],[22,[{"ar":"يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","lat":"Yā Dha-l-Jalāli wa-l-Ikrām","en":"O Possessor of Majesty and Honor.","de":"O Besitzer der Erhabenheit und Ehre.","open":false},{"ar":"سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ","lat":"Subḥāna Rabbika Rabbi-l-ʿizzati ʿammā yaṣifūn","en":"Glory be to your Lord, the Lord of Might, above what they describe.","de":"Gepriesen sei dein Herr, der Herr der Macht, über das, was sie Ihm zuschreiben.","open":false},{"ar":"وَسَلَامٌ عَلَى الْمُرْسَلِينَ","lat":"Wa salāmun ʿala-l-mursalīn","en":"And peace be upon the messengers.","de":"Und Friede sei auf den Gesandten.","open":false},{"ar":"وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ","lat":"Wa-l-ḥamdu lillāhi Rabbi-l-ʿālamīn","en":"And all praise is for Allah, Lord of the worlds.","de":"Und alles Lob gebührt Allah, dem Herrn der Welten.","open":false}]]];
